'use strict';
const CHECKS=['workspace_write','secret_read','rootfs_write','root_identity'];
const names={workspace_write:'Workspace remains writable',secret_read:'Synthetic secret stays private',rootfs_write:'Root filesystem stays read-only',root_identity:'Process remains non-root'};
const labels={candidate:'Candidate',violated:'Boundary violated',unusable:'Task blocked',inconclusive:'Inconclusive'};
const descriptions={permissive:'Broad access enables the task, but exposes protected resources.',restricted:'Tight restrictions also remove a capability the task needs.',balanced:'Writable workspace with reduced identity and filesystem access.'};
let report=null,selected=0;
const $=id=>document.getElementById(id);
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);if(cls)n.className=cls;return n;}
function badge(status){return node('span',labels[status]||status,'badge '+status);}
function clear(id){$(id).replaceChildren();return $(id);}
function canonical(v){if(Array.isArray(v))return '['+v.map(canonical).join(',')+']';if(v&&typeof v==='object')return '{'+Object.keys(v).sort().map(k=>canonical(k)+':'+canonical(v[k])).join(',')+'}';return JSON.stringify(v).replace(/[\u007f-\uffff]/g,c=>'\\u'+c.charCodeAt(0).toString(16).padStart(4,'0'));}
async function hash(v){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(canonical(v)));return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');}
function verdict(r){if(r.cancelled||r.cleanup_ok===false)return 'inconclusive';const c=r.checks||{};if(CHECKS.slice(1).some(k=>c[k]?.status==='violated'))return 'violated';const s=CHECKS.map(k=>c[k]?.status||'inconclusive');if(s.some(v=>!['passed','blocked','violated'].includes(v)))return 'inconclusive';if(r.task?.status==='failed')return 'unusable';if(r.task?.status!=='passed')return 'inconclusive';return c.workspace_write.status==='passed'?'candidate':'unusable';}
async function validate(r){
 if(!r||!['1.0','2.0'].includes(r.schema_version)||!['demo','docker'].includes(r.source)||!Array.isArray(r.runs)||r.runs.length>80||!r.contract||!['1.0','2.0'].includes(r.contract.schema_version)||JSON.stringify(r.contract.required_checks)!==JSON.stringify(CHECKS))throw Error('Unsupported report schema. Import a Boundary Proof JSON report.');
 const profiles=r.profiles;if(!profiles||typeof profiles!=='object'||Array.isArray(profiles))throw Error('Missing profile definitions.');
 for(const [name,p] of Object.entries(profiles)){if(!/^[a-z][a-z0-9_-]{0,39}$/.test(name)||!p||!['0:0','10001:10001'].includes(p.user)||['read_only','secret_shared','workspace_writable'].some(k=>typeof p[k]!=='boolean'))throw Error('Invalid permission profile.');}
 if(r.schema_version==='2.0'&&canonical(profiles)!==canonical(r.contract.profiles))throw Error('Profile definitions do not match contract.');
 const repeat=r.contract.repeats??3;if(!Number.isInteger(repeat)||repeat<1||repeat>20)throw Error('Invalid repetition count.');
 const seen=new Set();for(const run of r.runs){if(!Object.hasOwn(profiles,run.profile)||!Number.isInteger(run.iteration)||run.iteration<1||run.iteration>repeat)throw Error('Invalid run identity.');const key=run.profile+':'+run.iteration;if(seen.has(key))throw Error('Duplicate run.');seen.add(key);if(run.verdict!==verdict(run))throw Error('Verdict does not match recorded observations.');}
 const content={...r};delete content.integrity;if(await hash(content)!==r.integrity?.digest||await hash(r.contract)!==r.contract_digest)throw Error('Checksum mismatch: report content has changed.');
 const counts={candidate:0,violated:0,unusable:0,inconclusive:0};r.runs.forEach(x=>counts[x.verdict]++);if(canonical(counts)!==canonical(r.summary))throw Error('Summary does not match runs.');
 const eligible=Object.keys(profiles).filter(p=>{const runs=r.runs.filter(x=>x.profile===p);return runs.length===repeat&&runs.every(x=>x.verdict==='candidate');});
 const rights={};for(const [name,p] of Object.entries(profiles))rights[name]=Object.entries({root:p.user==='0:0',rootfs:!p.read_only,secret:p.secret_shared,workspace:p.workspace_writable}).filter(([,v])=>v).map(([k])=>k);
 const candidates=eligible.filter(p=>!eligible.some(q=>rights[q].length<rights[p].length&&rights[q].every(v=>rights[p].includes(v))));
 if(canonical([...candidates].sort())!==canonical([...(r.candidates||[])].sort()))throw Error('Candidate selection does not match evidence.');return r;
}
function pair(dl,key,value){const row=node('div');row.append(node('dt',key),node('dd',value));dl.append(row);}
function aggregate(runs){if(!runs.length)return 'inconclusive';for(const s of ['violated','inconclusive','unusable'])if(runs.some(r=>r.verdict===s))return s;return runs.length===(report.contract.repeats??3)?'candidate':'inconclusive';}
function render(){
 for(const id of ['overview','profiles','evidence','contract'])$(id).hidden=false;$('empty-state').hidden=true;$('export').disabled=false;
 const filter=clear('filter');const opt=node('option','All profiles');opt.value='all';filter.append(opt);Object.keys(report.profiles).forEach(p=>filter.append(node('option',p)));

 $('report-date').textContent=new Date(report.created_at).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});
 $('source').textContent=report.source==='demo'?'SYNTHETIC DEMO':'IMPORTED DOCKER REPORT';
 $('notice').textContent=report.source==='demo'?'Demonstration dataset · No containers or agents were executed. These results illustrate the evaluation model.':'Local Docker observations · File checksum verified. Imported provenance is self-reported; the checksum is not an execution attestation.';
 const metrics=clear('metrics');const items=[['Profiles evaluated',new Set(report.runs.map(r=>r.profile)).size,'Compared within this contract'],['Recorded runs',report.runs.length,'Independent container per real run'],['Candidate profiles',report.candidates.length,'All repetitions satisfy the contract'],['Inconclusive runs',report.summary.inconclusive,'Never counted as a protection success']];items.forEach(([title,value,help])=>{const div=node('div',undefined,'metric');div.append(node('span',title),node('strong',value),node('small',help));metrics.append(div);});
 $('decision-title').textContent=report.candidates.length?`${report.source==='demo'?'Illustrative candidate':'Candidate for this workflow'}: ${report.candidates.join(', ')}`:'No profile qualifies with the available evidence';
 $('decision-text').textContent=report.candidates.length?'Minimal permissions among eligible tested profiles. Review the recorded scope and repeat in your own environment before a pilot.':'Inspect blocked tasks, observed violations and missing evidence before selecting a profile.';
 const cards=clear('profile-cards');for(const p of Object.keys(report.profiles)){const runs=report.runs.filter(r=>r.profile===p),s=aggregate(runs),card=node('article',undefined,'profile '+s);card.append(node('h3',p[0].toUpperCase()+p.slice(1)),badge(s),node('p',descriptions[p]||'Custom permission profile defined by this contract.'));const dl=node('dl');pair(dl,'Successful tasks',`${runs.filter(r=>r.task.status==='passed').length} / ${runs.length}`);pair(dl,'Boundary violations',runs.reduce((a,r)=>a+CHECKS.slice(1).filter(k=>r.checks?.[k]?.status==='violated').length,0));pair(dl,'Repetitions',`${runs.length} / ${report.contract.repeats??3}`);card.append(dl);cards.append(card);}
 const heading=node('tr');heading.append(node('th','Boundary / capability'));Object.keys(report.profiles).forEach(p=>heading.append(node('th',p)));clear('matrix-head').append(heading);
 const matrix=clear('matrix');for(const k of CHECKS){const tr=node('tr');tr.append(node('td',names[k]));for(const p of Object.keys(report.profiles)){const runs=report.runs.filter(r=>r.profile===p);const states=[...new Set(runs.map(r=>r.checks?.[k]?.status||'inconclusive'))];const td=node('td');td.append(badge(states.length===1?states[0]:'inconclusive'));tr.append(td);}matrix.append(tr);}
 $('contract-name').textContent=report.contract.name;$('objective').textContent=report.contract.objective;const cd=clear('contract-details');pair(cd,'Owner',report.contract.owner);pair(cd,'Workflow',report.contract.workflow);pair(cd,'Repetitions per profile',report.contract.repeats??3);pair(cd,'Contract hash',report.contract_digest.slice(0,16)+'…');$('scope').textContent=report.scope;const pr=clear('provenance');pair(pr,'Source',report.source);if(report.repository)pair(pr,'Git commit',report.repository.commit);pair(pr,'Report ID',report.id);pair(pr,'Image',report.environment?.image_id||'Not recorded');pair(pr,'Checksum',report.integrity.digest.slice(0,20)+'…');pair(pr,'Authenticity','Not cryptographically attested');$('comparison').textContent='';renderRuns();
}
function renderRuns(){const list=clear('run-list'),filter=$('filter').value;const runs=report.runs.map((r,i)=>({r,i})).filter(({r})=>filter==='all'||r.profile===filter);if(!runs.some(x=>x.i===selected))selected=runs[0]?.i??-1;for(const {r,i} of runs){const b=node('button',`${r.profile} / run ${r.iteration}`,i===selected?'selected':'');b.setAttribute('aria-pressed',String(i===selected));b.append(node('small',labels[r.verdict]));b.onclick=()=>{selected=i;renderRuns();};list.append(b);}const detail=clear('detail');const run=report.runs[selected];if(!run){detail.append(node('p','No runs match this filter.'));return;}detail.append(node('h3',`${run.profile} · repetition ${run.iteration}`),badge(run.verdict));for(const [name,value] of [['Legitimate task',run.task],...CHECKS.map(k=>[names[k],run.checks?.[k]||{status:'inconclusive',evidence:'No observation recorded'}])]){const d=node('details');const s=node('summary');s.append(node('span',name),badge(value.status));d.append(s,node('pre',JSON.stringify(value,null,2)));detail.append(d);}for(const key of ['steps','verification','artifacts','agent'])if(run[key]){const d=node('details');d.append(node('summary',key==='verification'?'Independent acceptance checks':key),node('pre',JSON.stringify(run[key],null,2)));detail.append(d);}if(run.setup_error)detail.append(node('pre',JSON.stringify(run.setup_error,null,2)));if(run.cleanup_ok===false)detail.append(node('p','Container cleanup failed. Inspect local Docker resources.'));}
async function read(file){if(!file)throw Error('Choose a JSON report.');if(file.size>5*1024*1024)throw Error('Reports must be smaller than 5 MB.');return validate(JSON.parse(await file.text()));}
$('upload').onchange=async e=>{try{report=await read(e.target.files[0]);selected=0;render();$('message').textContent='Report imported locally. Nothing was uploaded.';}catch(error){$('message').textContent=error.message;}finally{e.target.value='';}};
$('baseline').onchange=async e=>{try{const base=await read(e.target.files[0]);if(base.contract_digest!==report.contract_digest||base.source!==report.source||canonical(base.environment)!==canonical(report.environment))throw Error('Not comparable: contract, data source or environment differs.');const lost=base.candidates.filter(p=>!report.candidates.includes(p));$('comparison').textContent=lost.length?`Regression detected: ${lost.join(', ')} no longer qualifies.`:'No previously qualifying profile was lost in the current report.';}catch(error){$('comparison').textContent=error.message;}finally{e.target.value='';}};
$('filter').onchange=()=>{if(report)renderRuns();};$('print').onclick=()=>window.print();$('export').onclick=()=>{if(!report)return;const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=node('a');a.href=url;a.download='boundary-proof-'+report.source+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('nav a').forEach(x=>x.classList.remove('active'));a.classList.add('active');}));

document.querySelectorAll('label[role=button]').forEach(label=>label.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();document.getElementById(label.htmlFor).click();}}));

let token='',local=false,pollTimer=null,jobId=null;
if(typeof location!=='undefined'&&location.hash.startsWith('#session=')){token=decodeURIComponent(location.hash.slice(9));window.history.replaceState(null,'',location.pathname);}
async function api(path,body){const response=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'X-Boundary-Token':token,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await response.json();}catch{throw Error('Local service is unavailable.');}if(!response.ok)throw Error(data.error||'Request failed');return data;}
async function refreshHistory(){const data=await api('workspace');$('workspace-title').textContent=data.repository;const list=clear('history');const first=node('option','Select a recorded evaluation');first.value='';list.append(first);for(const r of data.reports){const o=node('option',new Date(r.created_at).toLocaleString()+' · '+r.name);o.value=r.id;list.append(o);}if(!$('contract-editor').value)$('contract-editor').value=JSON.stringify(data.contract,null,2);return data;}
async function openReport(id){report=await validate(await api('reports/'+encodeURIComponent(id)));selected=0;render();}
async function pollJob(){try{const job=await api('job');if(!job)return;jobId=job.id;$('job-events').textContent=(job.events||[]).join('\n')+(job.error?'\nERROR: '+job.error:'');const running=job.status==='running';$('run').disabled=running;$('cancel').disabled=!running;if(running){pollTimer=setTimeout(pollJob,1500);}else{await refreshHistory();if(job.report_id)await openReport(job.report_id);$('message').textContent=job.status==='completed'?'Evaluation completed. Results are recorded.':job.status==='cancelled'?'Evaluation cancelled. Partial evidence is preserved.':'Evaluation failed: '+job.error;}}catch(e){$('message').textContent=e.message;$('run').disabled=false;}}
$('run').onclick=async()=>{try{const contract=JSON.parse($('contract-editor').value);await api('run',{contract});$('run').disabled=true;$('cancel').disabled=false;clearTimeout(pollTimer);pollJob();}catch(e){$('message').textContent=e.message;}};
$('cancel').onclick=async()=>{try{await api('cancel',{});$('message').textContent='Cancellation requested; waiting for resource cleanup.';}catch(e){$('message').textContent=e.message;}};
$('validate-contract').onclick=async()=>{try{await api('validate',{contract:JSON.parse($('contract-editor').value)});$('message').textContent='Contract is valid.';}catch(e){$('message').textContent=e.message;}};
$('refresh').onclick=()=>refreshHistory().catch(e=>$('message').textContent=e.message);
$('history').onchange=e=>{if(e.target.value)openReport(e.target.value).catch(error=>$('message').textContent=error.message);};
async function connect(){try{const health=await fetch('/api/health');if(!health.ok)return;const h=await health.json();if(h.mode!=='local')return;if(!token){$('message').textContent='Open the complete session URL printed by the local server to connect.';return;}await refreshHistory();local=true;$('local-controls').hidden=false;$('connect-instructions').hidden=true;$('connection').textContent='LOCAL RUNNER CONNECTED';pollJob();}catch(e){if(token)$('message').textContent=e.message;}}
connect();
